with base as (select id, customer_id, device, browser, started_at, country, datediff(current_date(), started_at) as days_since_started_at, coalesce(country, 'N/A') as country_filled from sessions where country is not null) select * from (select browser, device, days_since_started_at from base) src pivot (max(days_since_started_at) as value_sum for device in ('mobile', 'desktop', 'tablet'));
